// Generates the known-flawed LCA PDF fixtures (TASK-014).
// Run: node tests/fixtures/generate-flawed.mjs
// Each variant is a synthetic text-based LCA report with one planted error;
// everything else is internally consistent so tests isolate the planted flaw.

import { PDFDocument, StandardFonts } from "pdf-lib";
import { writeFileSync } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const here = path.dirname(fileURLToPath(import.meta.url));

const PAGE = { width: 595, height: 842, margin: 50, lineHeight: 14 };

async function buildPdf(sections) {
  const doc = await PDFDocument.create();
  const font = await doc.embedFont(StandardFonts.Helvetica);
  const bold = await doc.embedFont(StandardFonts.HelveticaBold);

  let page = doc.addPage([PAGE.width, PAGE.height]);
  let y = PAGE.height - PAGE.margin;

  const newPageIfNeeded = () => {
    if (y < PAGE.margin + PAGE.lineHeight) {
      page = doc.addPage([PAGE.width, PAGE.height]);
      y = PAGE.height - PAGE.margin;
    }
  };

  for (const section of sections) {
    newPageIfNeeded();
    if (section.heading) {
      y -= 10;
      newPageIfNeeded();
      page.drawText(section.heading, {
        x: PAGE.margin,
        y,
        size: 13,
        font: bold,
      });
      y -= PAGE.lineHeight + 4;
    }
    for (const line of section.lines ?? []) {
      newPageIfNeeded();
      page.drawText(line, { x: PAGE.margin, y, size: 9, font });
      y -= PAGE.lineHeight;
    }
  }

  return doc.save();
}

// Shared, internally consistent base report content. Numbers reconcile:
// stages sum to 0.5200; species sum to 0.5200; EoL net = gross - credits.
