const variants = [
  {
    // Planted error: GHG species total and stage totals reconcile to 0.5200,
    // but the headline claims 0.6100 (~17% off, far beyond the 2% tolerance).
    file: "flawed-ghg-mismatch.pdf",
    sections: baseSections({
      headlineKgCo2e: "0.6100",
      dataQuality: true,
      allocation:
        "Physical allocation by mass for all co-products per ISO 14044 Clause 4.3.4; no economic allocation applied.",
    }),
  },
  {
    // Planted error: the data quality section (ISO 14044 4.2.3.6) is absent.
    file: "flawed-missing-data-quality.pdf",
    sections: baseSections({
      headlineKgCo2e: "0.5200",
      dataQuality: false,
      allocation:
        "Physical allocation by mass for all co-products per ISO 14044 Clause 4.3.4; no economic allocation applied.",
    }),
  },
  {
    // Planted error: economic allocation chosen with physical allocation
    // feasible and no justification (violates the ISO 14044 4.3.4 hierarchy).
    file: "flawed-wrong-allocation.pdf",
    sections: baseSections({
      headlineKgCo2e: "0.5200",
      dataQuality: true,
      allocation:
        "Economic allocation (market price) applied to all co-products. Physical allocation was feasible but not used; no justification for departing from the ISO 14044 Clause 4.3.4 hierarchy is provided.",
    }),
  },
];

for (const variant of variants) {
  const bytes = await buildPdf(variant.sections);
  writeFileSync(path.join(here, variant.file), bytes);
  console.log(`wrote ${variant.file} (${bytes.length} bytes)`);
}
